// src/bracketSurfaceAuthoring.ts
var ATTR_RE = /\s+([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
var TOKEN_RE = /<!--[\s\S]*?-->|<\/?[A-Za-z][\w:-]*(?:\s+(?:[^<>"']|"[^"]*"|'[^']*')*)?\s*\/?>/g;
var VOID_TAGS = new Set("img br hr input meta link".split(" "));
var XML_PASSTHROUGH_TAGS = new Set(["image_request_error", "img"]);
var tagOf = (token) => /^<\/?([\w:-]+)/.exec(token)?.[1]?.toLowerCase() || "";
var attrsOf = (token) => Object.fromEntries([...String(token || "").matchAll(ATTR_RE)].map((match) => [match[1], match[2] ?? match[3] ?? ""]));
function parseLooseXml(source) {
  const stack = [];
  let root = null;
  let at = 0;
  for (const token of String(source || "").matchAll(TOKEN_RE)) {
    if (stack.length && token.index > at)
      stack.at(-1).children.push(String(source || "").slice(at, token.index));
    at = token.index + token[0].length;
    if (token[0].startsWith("<!--")) {
      stack.at(-1)?.children.push(token[0]);
      continue;
    }
    const tag = tagOf(token[0]);
    if (token[0].startsWith("</")) {
      if (stack.at(-1)?.tag !== tag)
        return null;
      stack.pop();
      continue;
    }
    const node = { tag, attrs: attrsOf(token[0]), children: [], void: /\/\s*>$/.test(token[0]) || VOID_TAGS.has(tag) };
    if (stack.length)
      stack.at(-1).children.push(node);
    else if (root)
      return null;
    else
      root = node;
    if (!node.void)
      stack.push(node);
  }
  return stack.length ? null : root;
}
function compactXmlControlSchema(node) {
  const attrs = Object.keys(node.attrs).map((key) => ` ${key}="…"`).join("");
  const children = node.children.map((child) => {
    if (typeof child === "string")
      return child.trim() ? "…" : "";
    return compactXmlControlSchema(child);
  }).join("");
  return `<${node.tag}${attrs}>${children}</${node.tag}>`;
}
function compactXmlSchemaFromXml(sampleXml) {
  const root = parseLooseXml(sampleXml);
  return root ? compactXmlControlSchema(root) : String(sampleXml || "");
}
function compactSurfacePromptModule(input) {
  const required = input.requiredMediaCount ?? 0;
  const maximum = input.maximumMediaCount == null ? "contract-defined" : String(input.maximumMediaCount);
  const media = required === 0 && input.maximumMediaCount === 0 ? "none" : `${required === 0 ? `optional, max=${maximum}` : `minimum=${required}, max=${maximum}`}${input.target ? `; target=${input.target}` : ""}${input.aspects?.length ? `; aspects=${input.aspects.join(",")}` : ""}. Use the exact owner position shown in SCHEMA; RULES override this summary when the Surface has multiple media roles.`;
  const sections = [
    `SURFACE: ${input.label.toUpperCase()}
FORMAT: compact-v1
ROOT: <${input.root}>`,
    input.triggerOverride?.trim() ? `TRIGGER OVERRIDE
${input.triggerOverride.trim()}` : "",
    `SCHEMA
${compactXmlSchemaFromXml(input.sampleXml)}`,
    `MEDIA
${media}`,
    input.specificRules?.trim() ? `RULES
${input.specificRules.trim()}` : ""
  ];
  return xmlAuthoringInstructions(sections.filter(Boolean).join(`

`));
}

