function applyPhoneAppDarkTheme(root) {
  const view = root.host.ownerDocument.defaultView;
  if (!view)
    return;
  const parse = (value) => {
    const match = /rgba?\(\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)(?:\s*,\s*(\d+(?:\.\d+)?))?\s*\)/i.exec(value);
    return match ? { r: Number(match[1]), g: Number(match[2]), b: Number(match[3]), a: match[4] === undefined ? 1 : Number(match[4]) } : null;
  };
  const luminance = ({ r, g, b }) => {
    const channel = (value) => {
      const n = value / 255;
      return n <= 0.04045 ? n / 12.92 : ((n + 0.055) / 1.055) ** 2.4;
    };
    return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b);
  };
  const hsl = ({ r, g, b }) => {
    r /= 255;
    g /= 255;
    b /= 255;
    const max = Math.max(r, g, b), min = Math.min(r, g, b), delta = max - min;
    let h = 0;
    const l = (max + min) / 2;
    let s = 0;
    if (delta) {
      s = delta / (1 - Math.abs(2 * l - 1));
      if (max === r)
        h = 60 * ((g - b) / delta % 6);
      else if (max === g)
        h = 60 * ((b - r) / delta + 2);
      else
        h = 60 * ((r - g) / delta + 4);
    }
    return { h: (h + 360) % 360, s, l };
  };
  const mutedBackground = (color) => {
    const tone = hsl(color);
    return tone.s < 0.16 ? "#191721" : `hsl(${Math.round(tone.h)} ${Math.round(Math.min(34, tone.s * 100))}% 17%)`;
  };
  const readableText = (color) => {
    const tone = hsl(color);
    return tone.s > 0.24 ? `hsl(${Math.round(tone.h)} ${Math.round(Math.min(78, Math.max(42, tone.s * 100)))}% 76%)` : "#f4f1f7";
  };
  const excluded = new Set(["IMG", "SVG", "VIDEO", "PICTURE", "CANVAS", "IFRAME"]);
  const control = root.querySelector(".rp-app-discussion");
  for (const element of Array.from(root.querySelectorAll("*"))) {
    if (excluded.has(element.tagName) || element.closest('.rr-amazon[data-amz-brand-preserve="true"],.rp-app-discussion,.rp-phone-composer,.rp-phone-responder,.rp-phone-bubble,.rp-conversations,.rp-conversation-trigger'))
      continue;
    const style = view.getComputedStyle(element), background = parse(style.backgroundColor), foreground = parse(style.color);
    const light = Boolean(background && background.a > 0.08 && luminance(background) > 0.55);
    const parentLight = Boolean(element.parentElement?.closest('[data-reverie-phone-darkened="true"]'));
    if (light) {
      element.dataset.reveriePhoneDarkened = "true";
      element.style.setProperty("background-color", mutedBackground(background), "important");
    }
    if ((light || parentLight) && foreground && luminance(foreground) < 0.19)
      element.style.setProperty("color", readableText(foreground), "important");
  }
  if (control)
    control.dataset.reveriePhoneControls = "true";
}

// src/phoneAppAccounts.ts
function phoneAvatarUrl(actor, state) {
  const value = actor && (state.portraits?.[actor.id]?.imageUrl || actor.avatarUrl);
  return safePhoneImageUrl(value) ? value : undefined;
}
function phoneAvatar(actor, state, label) {
  const avatar = document.createElement("span");
  avatar.className = "rp-account-avatar";
  const url = phoneAvatarUrl(actor, state);
  if (url) {
    const image = document.createElement("img");
    image.src = url;
    image.alt = `${label} profile picture`;
    image.loading = "lazy";
    avatar.append(image);
  } else
    avatar.textContent = label.trim().slice(0, 1) || "•";
  return avatar;
}
