// src/phonePreferences.ts
function normalizePhonePreferences(value) {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("Phone preferences are damaged. Existing inboxes were preserved.");
  if (value.connectionId !== undefined && value.connectionId !== null && (typeof value.connectionId !== "string" || value.connectionId.length > 150))
    throw new Error("Choose a valid phone reply connection.");
  if (value.contextMode !== undefined && !["automatic", "manual"].includes(value.contextMode))
    throw new Error("Choose Automatic or Manual phone context.");
  if (value.autoReply !== undefined && typeof value.autoReply !== "boolean")
    throw new Error("Choose Automatic or Manual phone replies.");
  return { connectionId: value.connectionId || null, autoReply: value.autoReply !== false, contextMode: value.contextMode || "automatic", incoming: normalizePhoneIncoming(value.incoming) };
}
function applyPhonePreferences(state, preferences) {
  return preferences ? { ...state, ...normalizePhonePreferences(preferences) } : state;
}

// src/phoneOperationId.ts
function phoneOperationId() {
  if (typeof crypto.randomUUID === "function")
    return crypto.randomUUID();
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  bytes[6] = bytes[6] & 15 | 64;
  bytes[8] = bytes[8] & 63 | 128;
  const hex = Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

// src/phoneHomeSwipe.ts
function mountPhoneHomeSwipe(root, turnPage) {
  let gesture = null;
  let suppressClickUntil = 0;
  const down = (event) => {
    suppressClickUntil = 0;
    gesture = null;
    if (event.isPrimary === false) {
      gesture = null;
      return;
    }
    if (event.pointerType === "mouse" && event.button !== 0)
      return;
    const path = event.composedPath();
    const screen = path.find((item) => item instanceof window.HTMLElement && item.matches(".home-screen"));
    if (!screen || Number(screen.dataset.appPages) < 2 || path.some((item) => item instanceof window.HTMLElement && item.matches(".app-pages, .notification, input, select, textarea, a, [contenteditable]")))
      return;
    gesture = { id: event.pointerId, screen, x: event.clientX, y: event.clientY, horizontal: false };
  };
  const move = (event) => {
    if (!gesture || gesture.id !== event.pointerId)
      return;
    if (!gesture.screen.isConnected) {
      gesture = null;
      return;
    }
    const dx = Math.abs(event.clientX - gesture.x), dy = Math.abs(event.clientY - gesture.y);
    if (!gesture.horizontal) {
      if (dy > 10 && dy >= dx) {
        gesture = null;
        return;
      }
      if (dx < 12 || dx < dy * 1.3)
        return;
      gesture.horizontal = true;
      gesture.screen.setPointerCapture?.(event.pointerId);
    }
    event.preventDefault();
  };
  const up = (event) => {
    if (!gesture || gesture.id !== event.pointerId)
      return;
    const completed = gesture;
    gesture = null;
    const dx = event.clientX - completed.x, dy = Math.abs(event.clientY - completed.y);
    if (!completed.screen.isConnected || !completed.horizontal)
      return;
    suppressClickUntil = Date.now() + 500;
    event.preventDefault();
    if (Math.abs(dx) >= 48 && Math.abs(dx) > dy * 1.3)
      turnPage(dx < 0 ? 1 : -1);
  };
  const cancel = () => {
    gesture = null;
  };
  const click = (event) => {
    if (event.detail === 0 || Date.now() > suppressClickUntil)
      return;
    suppressClickUntil = 0;
    event.preventDefault();
    event.stopImmediatePropagation();
  };
  root.addEventListener("pointerdown", down, true);
  root.addEventListener("pointermove", move, { capture: true, passive: false });
  root.addEventListener("pointerup", up, true);
  root.addEventListener("pointercancel", cancel, true);
  root.addEventListener("click", click, true);
  return () => {
    cancel();
    root.removeEventListener("pointerdown", down, true);
    root.removeEventListener("pointermove", move, true);
    root.removeEventListener("pointerup", up, true);
    root.removeEventListener("pointercancel", cancel, true);
    root.removeEventListener("click", click, true);
  };
}

