var node = (tag, className = "", content = "") => {
  const el = document.createElement(tag);
  el.className = className;
  el.textContent = content;
  return el;
};
var btn = (label, action, className = "secondary") => {
  const el = node("button", className, label);
  el.type = "button";
  el.addEventListener("click", action);
  return el;
};
function shadow(root) {
  const result = root.shadowRoot || root.attachShadow({ mode: "open" });
  const style = node("style");
  style.textContent = phoneWidgetCss + PHONE_ACCOUNTS_CSS;
  result.append(style);
  return result;
}
