    const active = activeId && studio.definitions[activeId]?.baseSurfaceId === definition.baseSurfaceId ? studio.definitions[activeId] : Object.values(studio.definitions).find((candidate) => candidate.baseSurfaceId === definition.baseSurfaceId && candidate.builtIn) || definition;
