          image.alt = String(row.slot || row.requestId || "Relay image");
          image.loading = "lazy";
          image.addEventListener("click", () => openImageUrl(imageUrl, image.alt, String(row.imageId || "")));
          const copy = document.createElement("div");
          copy.className = "dg-slot-meta";
