  function maybeOpenSlotImagePreviews() {
    const pending = records.filter((record) => record.status === "placement-pending" && record.previewPending && record.pendingPlacement);
    for (const key of [...openedSlotPreviewKeys]) {
      const record = recordByKey.get(key);
      if (!record || record.status !== "placement-pending" || !record.previewPending)
        openedSlotPreviewKeys.delete(key);
    }
    if (activeSlotPreviewKey)
      return;
    const next = pending.find((record) => !openedSlotPreviewKeys.has(record.key));
    if (!next)
      return;
    try {
      if (!openSlotImagePreview(next))
        return;
      openedSlotPreviewKeys.add(next.key);
      activeSlotPreviewKey = next.key;
    } catch (error) {
      if (!(error instanceof Error) || !error.message.includes("Maximum of 2 stacked modals"))
        throw error;
    }
  }
